"""flutter/: the pub package `yoin_symbols` (icon font + IconData constants)."""
from __future__ import annotations

import shutil

from common import FONT_FAMILY, MIRRORED, PUB_NAME, REGISTRY, REPO_URL, ROOT, camel, codepoints, names, version, write

FL = ROOT / "flutter"


def dart() -> str:
    cps = codepoints()
    lines = [
        "// Generated by generator/build.py from the icon sources. Do not edit by hand.",
        "",
        "/// Yoin Symbols for Flutter: light, rounded line icons as an icon font.",
        "///",
        "/// ```dart",
        "/// Icon(YoinSymbols.translate)",
        "/// ```",
        "library;",
        "",
        "import 'package:flutter/widgets.dart';",
        "",
        "/// Every Yoin symbol as an [IconData] for the [Icon] widget.",
        "///",
        "/// Size and colour come from [Icon] / [IconTheme] like any other icon font.",
        "@staticIconProvider",
        "abstract final class YoinSymbols {",
        "  /// Font family registered by this package.",
        f"  static const String fontFamily = '{FONT_FAMILY}';",
        "",
        "  /// Package that ships the font.",
        f"  static const String fontPackage = '{PUB_NAME}';",
        "",
    ]
    for n in names():
        lines.append(f"  /// {REGISTRY[n].zh} · `{n}`")
        # dart format (language 3.0 style): break after `=` when the line passes 80 columns
        decl = f"  static const IconData {camel(n)} ="
        named = ["fontFamily: fontFamily", "fontPackage: fontPackage"]
        if n in MIRRORED:
            named.append("matchTextDirection: true")
        init = f"IconData(0x{cps[n]:x}, {', '.join(named)});"
        if len(decl) + 1 + len(init) <= 80:
            lines.append(f"{decl} {init}")
        elif 6 + len(init) <= 80:
            lines += [decl, f"      {init}"]
        else:
            # still too long: named arguments go one per line
            lines.append(f"{decl} IconData(0x{cps[n]:x},")
            lines += [f"      {a}," for a in named[:-1]] + [f"      {named[-1]});"]
        lines.append("")
    lines.append("  /// Every symbol by its canonical snake_case name, for galleries and pickers.")
    lines.append("  static const Map<String, IconData> all = <String, IconData>{")
    lines += [f"    '{n}': {camel(n)}," for n in names()]
    lines += ["  };", "}", ""]
    return "\n".join(lines)


def pubspec() -> str:
    return f"""name: {PUB_NAME}
description: >-
  Yoin Symbols: light, rounded line icons with continuous-curvature containers,
  shipped as an icon font for Flutter's Icon widget.
version: {version()}
homepage: {REPO_URL}
repository: {REPO_URL}/tree/main/flutter
issue_tracker: {REPO_URL}/issues
topics:
  - icons
  - icon-font
  - symbols

environment:
  sdk: ^3.0.0
  flutter: ">=3.10.0"

dependencies:
  flutter:
    sdk: flutter

flutter:
  fonts:
    - family: {FONT_FAMILY}
      fonts:
        - asset: fonts/{FONT_FAMILY}.ttf
"""


def build(font_ttf) -> int:
    write(FL / "lib" / f"{PUB_NAME}.dart", dart())
    write(FL / "pubspec.yaml", pubspec())
    (FL / "fonts").mkdir(parents=True, exist_ok=True)
    shutil.copyfile(font_ttf, FL / "fonts" / f"{FONT_FAMILY}.ttf")
    shutil.copyfile(ROOT / "LICENSE", FL / "LICENSE")
    shutil.copyfile(ROOT / "CHANGELOG.md", FL / "CHANGELOG.md")
    return len(names())
